/// sectors.
pub(super) fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
    let an = self.nodes[a].next;
    let ap = self.nodes[a].prev;
    let bi = self.nodes[b].i;
    let bp = self.nodes[b].prev;
    let bn = self.nodes[b].next;

    self.nodes[an].i != bi
        && self.nodes[ap].i != bi
        && !self.intersects_polygon(a, b) // doesn't intersect other edges
        && ((self.locally_inside(a, b)
            && self.locally_inside(b, a)
            && self.middle_inside(a, b) // locally visible
            // does not create opposite-facing sectors
            && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
            // special zero-length case
            || (self.equals(a, b)
                && self.area(ap, a, an) > 0.0
                && self.area(bp, b, bn) > 0.0))
}

/// Whether sector in vertex `m` contains the sector in vertex `p` in the same
/// coordinates.
pub(super) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
    let mp = self.nodes[m].prev;
    let pn = self.nodes[p].next;
    self.area(mp, m, p) < 0.0 && self.area(pn, m, mp) < 0.0
}

/// Find the leftmost node of a polygon ring.
pub(super) fn get_leftmost(&self, start: usize) -> usize {
    let mut p = start;
    let mut leftmost = start;
    loop {
        let (np, nl) = (&self.nodes[p], &self.nodes[leftmost]);
        if np.x < nl.x || (np.x == nl.x && np.y < nl.y) {
            leftmost = p;
        }
        p = self.nodes[p].next;
        if p == start {
            return leftmost;
        }
    }
}

/// Link two polygon vertices with a bridge; if the vertices belong to the same
/// ring, it splits the polygon into two. If one belongs to the outer ring and
/// another to a hole, it merges it into a single ring.
pub(super) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
    let (ai, ax, ay) = {
        let n = &self.nodes[a];
        (n.i, n.x, n.y)
    };
    let (bi, bx, by) = {
        let n = &self.nodes[b];
        (n.i, n.x, n.y)
    };
    let a2 = self.construct(ai, ax, ay);
    let b2 = self.construct(bi, bx, by);
    let an = self.nodes[a].next;

  1	//! Ear-clipping polygon triangulator.
  2	//!
  3	//! A `std`-only port of the `mapbox::earcut` 2.2.x algorithm: build a circular
  4	//! doubly-linked list from the outer ring, splice holes in as bridges, then clip
  5	//! ears one by one. When no ear can be found the algorithm escalates through
  6	//! three fallbacks — filter collinear points, cure local self-intersections,
  7	//! and finally split the ring on a valid diagonal — which is what makes a
  8	//! self-intersecting input such as a spiral triangulable at all.
  9	//!
 10	//! The triangle indices are emitted in exactly the order the reference
 11	//! implementation emits them; the fallback passes are order-sensitive, so the
 12	//! control flow is kept structurally identical rather than idiomatically
 13	//! restructured.
 14	
