436	    /// Try splitting polygon into two and triangulate them independently.
437	    fn split_earcut(&mut self, start: usize) {
438	        // look for a valid diagonal that divides the polygon into two
439	        let mut a = start;
440	        loop {
441	            let an = self.nodes[a].next;
442	            let mut b = self.nodes[an].next;
443	
444	            while b != self.nodes[a].prev {
445	                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
446	                    // split the polygon in two by the diagonal
447	                    let mut c = self.split_polygon(a, b);
448	
449	                    // filter colinear points around the cuts
450	                    let a_next = self.nodes[a].next;
451	                    let a2 = self.filter_points(a, a_next);
452	                    let c_next = self.nodes[c].next;
453	                    c = self.filter_points(c, c_next);
454	
455	                    // run earcut on each half
456	                    self.earcut_linked(a2, 0);
457	                    self.earcut_linked(c, 0);
458	                    return;
459	                }
460	                b = self.nodes[b].next;
461	            }
462	            a = self.nodes[a].next;
463	            if a == start {
464	                return;
465	            }
466	        }
467	    }
