48	//! Generation of the Archimedean spiral ring fed to the triangulator.
49	
50	use std::f64::consts::PI;
51	
52	/// Sample `2 * n` points of a spiral whose radius grows linearly with the
53	/// parameter `t` over two full turns.
54	///
55	/// The arithmetic mirrors the C++ source term by term — `t` is the integer ratio
56	/// `i / (n * 2)` and the angle is `(4.0 * PI) * t` — so the sampled coordinates
57	/// are bit-identical doubles.
58	pub fn spiral(n: i32) -> Vec<[f64; 2]> {
59	    let count = n.wrapping_mul(2);
60	    let mut points: Vec<[f64; 2]> = Vec::new();
61	
62	    let mut i: i32 = 0;
63	    while i < count {
64	        let t = f64::from(i) / f64::from(count);
65	        let radius = t;
66	        let angle = 4.0 * PI * t;
67	        points.push([radius * angle.cos(), radius * angle.sin()]);
68	        i += 1;
69	    }
70	
71	    points
72	}
