     1	//! Geometric predicates over arena nodes.
     2	//!
     3	//! Every comparison here is performed on `f64` exactly as the reference
     4	//! implementation does: no epsilons, no reordering of the arithmetic. The
     5	//! triangulation of a self-intersecting ring is decided by the sign of these
     6	//! expressions, so the operand order is load-bearing.
     7	
     8	use super::node::NIL;
     9	use super::Earcut;
    10	
    11	impl Earcut {
    12	    /// Signed area of the triangle `(p, q, r)`, doubled.
    13	    pub(super) fn area(&self, p: usize, q: usize, r: usize) -> f64 {
    14	        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
    15	        (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
    16	    }
    17	
    18	    /// Check if two points are equal.
    19	    pub(super) fn equals(&self, p1: usize, p2: usize) -> bool {
    20	        let (p1, p2) = (&self.nodes[p1], &self.nodes[p2]);
    21	        p1.x == p2.x && p1.y == p2.y
    22	    }
    23	
    24	    #[allow(clippy::too_many_arguments)]
    25	    pub(super) fn point_in_triangle(
    26	        &self,
    27	        ax: f64,
    28	        ay: f64,
    29	        bx: f64,
    30	        by: f64,
    31	        cx: f64,
    32	        cy: f64,
    33	        px: f64,
    34	        py: f64,
    35	    ) -> bool {
    36	        (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
    37	            && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
    38	            && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
    39	    }
    40	
    41	    /// `(0.0 < val) - (val < 0.0)`, i.e. the sign as -1, 0 or 1.
    42	    pub(super) fn sign(val: f64) -> i32 {
    43	        i32::from(0.0 < val) - i32::from(val < 0.0)
    44	    }
    45	
    46	    /// For collinear points `p`, `q`, `r`, check if point `q` lies on segment `pr`.
    47	    pub(super) fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
    48	        let (p, q, r) = (&self.nodes[p], &self.nodes[q], &self.nodes[r]);
    49	        q.x <= p.x.max(r.x) && q.x >= p.x.min(r.x) && q.y <= p.y.max(r.y) && q.y >= p.y.min(r.y)
    50	    }
    51	
    52	    /// Check if two segments intersect.
    53	    pub(super) fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
    54	        let o1 = Self::sign(self.area(p1, q1, p2));
    55	        let o2 = Self::sign(self.area(p1, q1, q2));
    56	        let o3 = Self::sign(self.area(p2, q2, p1));
    57	        let o4 = Self::sign(self.area(p2, q2, q1));
    58	
    59	        if o1 != o2 && o3 != o4 {
    60	            return true; // general case
    61	        }
    62	
    63	        // p1, q1 and p2 are collinear and p2 lies on p1q1
    64	        if o1 == 0 && self.on_segment(p1, p2, q1) {
    65	            return true;
    66	        }
    67	        // p1, q1 and q2 are collinear and q2 lies on p1q1
    68	        if o2 == 0 && self.on_segment(p1, q2, q1) {
    69	            return true;
    70	        }
    71	        // p2, q2 and p1 are collinear and p1 lies on p2q2
    72	        if o3 == 0 && self.on_segment(p2, p1, q2) {
    73	            return true;
    74	        }
    75	        // p2, q2 and q1 are collinear and q1 lies on p2q2
    76	        if o4 == 0 && self.on_segment(p2, q1, q2) {
    77	            return true;
    78	        }
    79	
    80	        false
    81	    }
    82	
    83	    /// Check if a polygon diagonal intersects any polygon segment.
    84	    pub(super) fn intersects_polygon(&self, a: usize, b: usize) -> bool {
    85	        let ai = self.nodes[a].i;
    86	        let bi = self.nodes[b].i;
    87	        let mut p = a;
    88	        loop {
    89	            let pn = self.nodes[p].next;
    90	            if self.nodes[p].i != ai
    91	                && self.nodes[pn].i != ai
    92	                && self.nodes[p].i != bi
    93	                && self.nodes[pn].i != bi
    94	                && self.intersects(p, pn, a, b)
    95	            {
    96	                return true;
    97	            }
    98	            p = pn;
    99	            if p == a {
   100	                return false;
   101	            }
   102	        }
   103	    }
   104	
   105	    /// Check if a polygon diagonal is locally inside the polygon.
   106	    pub(super) fn locally_inside(&self, a: usize, b: usize) -> bool {
   107	        let ap = self.nodes[a].prev;
   108	        let an = self.nodes[a].next;
   109	        if self.area(ap, a, an) < 0.0 {
   110	            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
   111	        } else {
   112	            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
   113	        }
   114	    }
   115	
   116	    /// Check if the middle point of a polygon diagonal is inside the polygon.
   117	    pub(super) fn middle_inside(&self, a: usize, b: usize) -> bool {
   118	        let mut p = a;
   119	        let mut inside = false;
   120	        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
   121	        let py = (self.nodes[a].y + self.nodes[b].y) / 2.0;
   122	        loop {
   123	            let pn = self.nodes[p].next;
   124	            let (cur, nxt) = (&self.nodes[p], &self.nodes[pn]);
   125	            if ((cur.y > py) != (nxt.y > py))
   126	                && nxt.y != cur.y
   127	                && (px < (nxt.x - cur.x) * (py - cur.y) / (nxt.y - cur.y) + cur.x)
   128	            {
   129	                inside = !inside;
   130	            }
   131	            p = pn;
   132	            if p == a {
   133	                return inside;
   134	            }
   135	        }
   136	    }
   137	
   138	    /// Check whether a diagonal between two polygon nodes lies within the polygon
   139	    /// area, does not intersect other edges and does not create opposite-facing
   140	    /// sectors.
   141	    pub(super) fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
   142	        let an = self.nodes[a].next;
   143	        let ap = self.nodes[a].prev;
   144	        let bi = self.nodes[b].i;
   145	        let bp = self.nodes[b].prev;
   146	        let bn = self.nodes[b].next;
   147	
   148	        self.nodes[an].i != bi
   149	            && self.nodes[ap].i != bi
   150	            && !self.intersects_polygon(a, b) // doesn't intersect other edges
   151	            && ((self.locally_inside(a, b)
   152	                && self.locally_inside(b, a)
   153	                && self.middle_inside(a, b) // locally visible
   154	                // does not create opposite-facing sectors
   155	                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
   156	                // special zero-length case
   157	                || (self.equals(a, b)
   158	                    && self.area(ap, a, an) > 0.0
   159	                    && self.area(bp, b, bn) > 0.0))
   160	    }
   161	
   162	    /// Whether sector in vertex `m` contains the sector in vertex `p` in the same
   163	    /// coordinates.
   164	    pub(super) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
   165	        let mp = self.nodes[m].prev;
   166	        let pn = self.nodes[p].next;
   167	        self.area(mp, m, p) < 0.0 && self.area(pn, m, mp) < 0.0
   168	    }
   169	
   170	    /// Find the leftmost node of a polygon ring.
   171	    pub(super) fn get_leftmost(&self, start: usize) -> usize {
   172	        let mut p = start;
   173	        let mut leftmost = start;
   174	        loop {
   175	            let (np, nl) = (&self.nodes[p], &self.nodes[leftmost]);
   176	            if np.x < nl.x || (np.x == nl.x && np.y < nl.y) {
   177	                leftmost = p;
   178	            }
   179	            p = self.nodes[p].next;
   180	            if p == start {
   181	                return leftmost;
   182	            }
   183	        }
   184	    }
   185	
   186	    /// Link two polygon vertices with a bridge; if the vertices belong to the same
   187	    /// ring, it splits the polygon into two. If one belongs to the outer ring and
   188	    /// another to a hole, it merges it into a single ring.
   189	    pub(super) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
   190	        let (ai, ax, ay) = {
   191	            let n = &self.nodes[a];
   192	            (n.i, n.x, n.y)
   193	        };
   194	        let (bi, bx, by) = {
   195	            let n = &self.nodes[b];
   196	            (n.i, n.x, n.y)
   197	        };
   198	        let a2 = self.construct(ai, ax, ay);
   199	        let b2 = self.construct(bi, bx, by);
   200	        let an = self.nodes[a].next;
   201	        let bp = self.nodes[b].prev;
   202	
   203	        self.nodes[a].next = b;
   204	        self.nodes[b].prev = a;
   205	
   206	        self.nodes[a2].next = an;
   207	        self.nodes[an].prev = a2;
   208	
   209	        self.nodes[b2].next = a2;
   210	        self.nodes[a2].prev = b2;
   211	
   212	        self.nodes[bp].next = b2;
   213	        self.nodes[b2].prev = bp;
   214	
   215	        b2
   216	    }
   217	
   218	    /// Remove a node from both the vertex ring and the z-order list.
   219	    pub(super) fn remove_node(&mut self, p: usize) {
   220	        let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
   221	        self.nodes[next].prev = prev;
   222	        self.nodes[prev].next = next;
   223	
   224	        let (prev_z, next_z) = (self.nodes[p].prev_z, self.nodes[p].next_z);
   225	        if prev_z != NIL {
   226	            self.nodes[prev_z].next_z = next_z;
   227	        }
   228	        if next_z != NIL {
   229	            self.nodes[next_z].prev_z = prev_z;
   230	        }
   231	    }
   232	}
